<?php
require_once __DIR__.'/../includes/auth.php';auth_require();$error='';$sale=(int)($_GET['sale_id']??$_POST['sale_id']??0);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{$quantities=$_POST['quantities']??[];if(!is_array($quantities))throw new InvalidArgumentException('Invalid return quantities.');sale_return_post($sale,$quantities,(string)($_POST['reason']??''),(string)($_POST['request_key']??''));redirect(BASE_URL.'modules/sales_returns.php');}catch(Throwable $e){http_response_code($e->getCode()===403?403:422);$error=public_error($e);}
$pageTitle=__t('Sales returns & refunds','برگشت فروش و پول','د پلور او پیسو ستنول');require __DIR__.'/../includes/header.php';?>
<h1><?= sanitize($pageTitle) ?></h1><p><?= __t('Return all or part of an invoice. Outstanding credit is reduced first; any paid portion becomes a refund payable. Actual refunds are recorded separately in Cash & bank. Original invoices and receipts are retained.','بل را کامل یا قسمتی برگشت دهید. نخست طلب باقی‌مانده کم می‌شود؛ بخش پرداخت‌شده به بدهی برگشت پول تبدیل می‌شود. پرداخت واقعی پول از صندوق و بانک ثبت می‌شود. بل و رسیدهای اصلی حفظ می‌شوند.','بل بشپړ یا برخه بېرته وګرځوئ؛ پیسې په نغدو برخه کې جلا ثبتېږي.') ?></p><?php if($error):?><p class="alert alert-danger" role="alert"><?= sanitize($error) ?></p><?php endif ?>
<section class="card modern-form"><form method="get"><label><?= __t('Invoice','بل','بل') ?><select name="sale_id" class="form-control"><?php $q=$pdo->prepare("SELECT s.id,s.invoice_no,s.total_amount,s.currency_code FROM sales s WHERE s.shop_id=? AND NOT EXISTS(SELECT 1 FROM sales_returns r WHERE r.sale_id=s.id AND r.shop_id=s.shop_id AND r.status='posted') ORDER BY s.id DESC LIMIT 250");$q->execute([shop_id()]);foreach($q->fetchAll() as $s):?><option value="<?= (int)$s['id'] ?>" <?= $sale===(int)$s['id']?'selected':'' ?>><?= sanitize($s['invoice_no'].' · '.$s['total_amount'].' '.$s['currency_code']) ?></option><?php endforeach ?></select></label><button class="btn btn-primary"><?= __t('Open invoice','بازکردن بل','بل پرانیزئ') ?></button></form></section>
<?php if($sale):$q=$pdo->prepare('SELECT * FROM sales WHERE id=? AND shop_id=?');$q->execute([$sale,shop_id()]);$source=$q->fetch();if(!$source)access_deny(404,'not_found','Invoice unavailable.');$q=$pdo->prepare('SELECT i.*,(SELECT COALESCE(SUM(r.quantity),0) FROM return_lines r WHERE r.sale_item_id=i.id AND r.shop_id=i.shop_id) AS returned_qty FROM sale_items i WHERE i.sale_id=? AND i.shop_id=? ORDER BY i.id');$q->execute([$sale,shop_id()]);?>
<section class="card modern-form"><form method="post"><?= csrf_field() ?><input name="action" type="hidden" value="approve_return"><input name="sale_id" type="hidden" value="<?= $sale ?>"><input name="request_key" type="hidden" value="<?= bin2hex(random_bytes(16)) ?>"><h2><?= sanitize($source['invoice_no']) ?></h2><div class="form-grid"><?php foreach($q->fetchAll() as $i):$left=dec_sub($i['quantity'],$i['returned_qty'],3);?><label><?= sanitize($i['product_name'].' · '.__t('Available to return','قابل برگشت','د ستنولو وړ').': '.$left) ?><input class="form-control" name="quantities[<?= (int)$i['id'] ?>]" type="number" min="0" max="<?= sanitize($left) ?>" step="0.001" value="0"></label><?php endforeach ?></div><label><?= __t('Return reason','دلیل برگشت','د ستنولو لامل') ?><textarea class="form-control" name="reason" minlength="3" maxlength="500" required></textarea></label><button class="btn btn-primary"><?= __t('Approve return','تأیید برگشت','ستنول تایید') ?></button></form></section><?php endif ?>
<?php require __DIR__.'/../includes/footer.php'; ?>
